insert into public.form_tips (question, answer, sort_order) values
('Prior internship experience?', 'If you have never had a real internship, choose none. Academic projects and capstones are not internships, even if they were for a real client.', 10),
('Highest completed qualification?', 'Being enrolled in BSIT is not a completed degree. Pick the qualification you have actually finished, and look through the options for an "undergraduate" or "currently studying" choice.', 20),
('Tools and proficiency checklists (Office, build tools, languages)?', 'Only tick what you actually use. If you have not used a tool yourself, leave it unticked. Using React does not mean you have used a specific build tool.', 30),
('English or other proficiency level?', 'Pick the level you can back up in an interview. Do not claim professional fluency without a basis.', 40),
('LECPA or licensure exam?', 'Not applicable for BSIT. Choose N/A if the form allows it.', 50),
('Other applications in progress?', 'Answer yes while you have applications going, and describe only real stages (applied, interview). Never mention offers you do not have.', 60),
('Right to work or citizenship?', 'Select only what is accurate for you.', 70),
('JobStreet quick apply cover letter?', 'Quick apply can reuse the cover letter from your last application. Open it and replace the company and role before you submit.', 80),
('Academic schedule conflicts?', 'Answer from your real schedule. Check with your FIC if your OJT overlaps classes.', 90);
